def max_Product(nums):
    if not nums:
        return None

    # Find the two largest positive numbers
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in nums:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate products
    product_pos = max1 * max2
    product_neg = min1 * min2

    if product_neg > product_pos:
        return (min1, min2)
    else:
        return (max1, max2)

