def largest_subset(nums):
    if not nums:
        return 0

    # Sort the list to make it easier to find multiples
    nums.sort()

    n = len(nums)
    dp = [1] * n  # dp[i] represents the size of the largest subset ending at index i

    for i in range(n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

