def get_ludic(n):
    def is_ludic(num):
        if num <= 1:
            return False
        factors = []
        d = 2
        temp = num
        while d * d <= temp:
            if temp % d == 0:
                factors.append(d)
                temp //= d
            else:
                d += 1
        if temp > 1:
            factors.append(temp)

        for factor in factors:
            if not is_ludic(factor):
                return False
        return True

    result = []
    for i in range(n + 1):
        if is_ludic(i):
            result.append(i)
    return result

